<script setup lang="ts">
import type { SpeakingPart } from '~/types/ielts'
import { libraryAPI } from '~/services/ielts'

/**
 * A Speaking part: its questions, the pictures and the cue card or debate table, and what the test
 * brings itself: the examiner's audio for each turn and a sample answer (else generated by AI).
 */
definePageMeta({ middleware: 'admin' })

const route = useRoute()
const toast = useToast()
const { confirm } = useDialogs()
const id = computed(() => String(route.params.id))
const lastList = useBuilderList()
const back = computed(() => (route.query.test ? `/builder/tests/${route.query.test}` : lastList.value ?? '/builder?tab=speaking'))

const { data: part, status, error } = useAsyncData<SpeakingPart>(() => `speaking-part:${id.value}`, () => libraryAPI.speakingPart(id.value), { watch: [id] })
useSeoMeta({ title: () => `${part.value?.title || 'Speaking part'} — Builder`, robots: 'noindex' })

interface QuestionForm { text: string, audioRef: string | null, sampleAnswer: string }
const form = reactive({
  partNumber: 1 as 1 | 2 | 3 | 4, title: '', cueCard: '', imageRef: null as string | null, prepSeconds: null as number | null, speakSeconds: null as number | null,
  audioRef: null as string | null, sampleAnswer: '', questions: [] as QuestionForm[]
})

const payload = () => ({
  partNumber: form.partNumber, title: form.title.trim() || null, cueCard: form.cueCard.trim() || null, imageRef: form.imageRef,
  prepSeconds: form.prepSeconds, speakSeconds: form.speakSeconds,
  audioRef: form.audioRef?.trim() || null, sampleAnswer: form.sampleAnswer.trim() || null,
  questions: form.questions.filter(q => q.text.trim()).map(q => ({ text: q.text.trim(), audioRef: q.audioRef?.trim() || null, sampleAnswer: q.sampleAnswer.trim() || null }))
})
const autosave = useAutosave(payload, async () => {
  const saved = await libraryAPI.updateSpeakingPart(id.value, payload())
  if (part.value) part.value.imageUrl = saved.imageUrl
})
watch(part, (p, old) => {
  if (!p || p.id === old?.id) return
  Object.assign(form, {
    partNumber: p.partNumber as 1 | 2 | 3 | 4, title: p.title ?? '', cueCard: p.cueCard ?? '', imageRef: p.imageRef ?? null, prepSeconds: p.prepSeconds ?? null, speakSeconds: p.speakSeconds ?? null,
    audioRef: p.audioRef ?? null, sampleAnswer: p.sampleAnswer ?? '',
    questions: [...p.questions].sort((a, b) => a.position - b.position).map(q => ({ text: q.text, audioRef: q.audioRef ?? null, sampleAnswer: q.sampleAnswer ?? '' }))
  })
  nextTick(() => autosave.markClean())
}, { immediate: true })
watch(autosave.state, (s) => { if (s === 'error') toast.add({ title: 'Changes not saved', color: 'error' }) })

const newQuestion = ref('')
function addQuestion() {
  if (!newQuestion.value.trim()) return
  form.questions.push({ text: newQuestion.value.trim(), audioRef: null, sampleAnswer: '' })
  newQuestion.value = ''
}
function move(i: number, d: number) {
  const [q] = form.questions.splice(i, 1)
  form.questions.splice(i + d, 0, q!)
}

async function remove() {
  if (!await confirm({ title: 'Delete this Speaking part?', description: 'A part used in a test cannot be deleted.', confirmLabel: 'Delete' })) return
  try {
    await libraryAPI.deleteSpeakingPart(id.value)
    await navigateTo(back.value)
  } catch (e) {
    toast.add({ title: 'Not deleted', description: errorMessage(e), color: 'error' })
  }
}
// Which question shows its audio and sample answer.
const openQuestion = ref<number | null>(null)
/** A long turn (the card, the statement) has one audio and one sample for the part. */
const longTurn = computed(() => !answeredByQuestion(form.partNumber, part.value?.exam))
const saveLabel = computed(() => ({ idle: '', dirty: 'Unsaved changes', saving: 'Saving…', saved: 'Saved', error: 'Not saved' })[autosave.state.value])
const ielts = computed(() => part.value?.exam === 'IELTS')
const hint = computed(() => (ielts.value
  ? {
      1: 'Part 1: questions about the candidate and familiar topics, answered at once (about 30 seconds each), four to five minutes in all.',
      2: 'Part 2: the cue card, with the points to cover — one minute to prepare, up to two minutes to speak.',
      3: 'Part 3: discussion questions linked to Part 2, answered at once (about a minute each).'
    }
  : {
      1: 'Part 1.1: three questions about the candidate — 5 seconds to think, 30 seconds to answer each.',
      2: 'Part 1.2: two pictures to compare, then questions about them — 10 seconds to think, 30–45 seconds each.',
      3: 'Part 2: a picture and a cue card — one minute to prepare, two minutes to speak.',
      4: 'Part 3: a debate topic with points for and against — one minute to prepare, two minutes to speak.'
    } as Record<number, string>)[form.partNumber])
</script>

<template>
  <AppPage
    :title="part ? (part.title || `Speaking ${speakingPartLabel(part.partNumber, part.exam)}`) : 'Speaking part'"
    :back="back"
    wide
  >
    <template #actions>
      <span class="text-xs text-muted max-sm:hidden">{{ saveLabel }}</span>
      <UButton
        icon="i-lucide-trash"
        color="neutral"
        variant="ghost"
        square
        @click="remove"
      />
    </template>

    <div
      v-if="status === 'pending' && !part"
      class="grid gap-4"
    >
      <USkeleton class="h-80" />
    </div>
    <UEmpty
      v-else-if="error"
      icon="i-lucide-circle-alert"
      title="This part could not be opened"
      :description="errorMessage(error)"
    />
    <div
      v-else-if="part"
      class="grid lg:grid-cols-[minmax(0,1fr)_320px] gap-6 items-start"
    >
      <div class="grid gap-4 min-w-0">
        <UAlert
          icon="i-lucide-info"
          color="neutral"
          variant="subtle"
          :description="hint"
        />
        <UCard v-if="ielts ? form.partNumber === 2 : form.partNumber !== 1">
          <template #header>
            <p class="font-semibold text-highlighted">
              {{ form.partNumber === 2 ? 'Pictures' : 'Picture' }}
            </p>
          </template>
          <BuilderFileField
            v-model="form.imageRef"
            kind="image"
            :url="part.imageUrl"
          />
        </UCard>
        <UCard v-if="ielts ? form.partNumber === 2 : form.partNumber >= 3">
          <template #header>
            <p class="font-semibold text-highlighted">
              {{ form.partNumber === 4 ? 'Debate table' : 'Cue card' }}
            </p>
          </template>
          <BuilderRichEditor
            v-model="form.cueCard"
            toolbar="basic"
            :placeholder="form.partNumber === 4 ? 'The topic, with a table of points For and Against.' : 'The topic and the points to talk about.'"
            min-height="min-h-40"
          />
        </UCard>
        <UCard v-if="longTurn">
          <template #header>
            <p class="font-semibold text-highlighted">
              Examiner audio and sample answer
            </p>
          </template>
          <div class="grid gap-3">
            <UFormField
              label="Examiner audio"
              help="The card or statement read aloud. Without one, the voice is generated once."
            >
              <BuilderFileField
                v-model="form.audioRef"
                kind="audio"
                :url="part.audioUrl"
              />
            </UFormField>
            <UFormField
              label="Sample answer"
              help="Shown after the attempt and in AI feedback, so the AI does not write one."
            >
              <UTextarea
                v-model="form.sampleAnswer"
                :rows="6"
                autoresize
                class="w-full"
                data-testid="part-sample"
              />
            </UFormField>
          </div>
        </UCard>
        <UCard :ui="{ body: 'p-0 sm:p-0' }">
          <template #header>
            <p class="font-semibold text-highlighted">
              Questions
            </p>
          </template>
          <ol class="divide-y divide-default">
            <li
              v-for="(q, i) in form.questions"
              :key="i"
              class="px-4 py-2"
            >
              <div class="flex items-center gap-2">
                <span class="text-xs text-muted tabular-nums w-5">{{ i + 1 }}.</span>
                <UInput
                  v-model="q.text"
                  variant="none"
                  class="flex-1"
                />
                <UButton
                  v-if="!longTurn"
                  :icon="q.audioRef || q.sampleAnswer.trim() ? 'i-lucide-volume-2' : 'i-lucide-plus'"
                  :label="q.audioRef || q.sampleAnswer.trim() ? [q.audioRef ? 'audio' : '', q.sampleAnswer.trim() ? 'sample' : ''].filter(Boolean).join(' · ') : 'Audio & sample'"
                  size="xs"
                  :color="q.audioRef || q.sampleAnswer.trim() ? 'primary' : 'neutral'"
                  variant="soft"
                  :data-testid="`question-extras-${i}`"
                  @click="openQuestion = openQuestion === i ? null : i"
                />
                <UButton
                  icon="i-lucide-chevron-up"
                  size="xs"
                  color="neutral"
                  variant="ghost"
                  square
                  :disabled="i === 0"
                  @click="move(i, -1)"
                />
                <UButton
                  icon="i-lucide-chevron-down"
                  size="xs"
                  color="neutral"
                  variant="ghost"
                  square
                  :disabled="i === form.questions.length - 1"
                  @click="move(i, 1)"
                />
                <UButton
                  icon="i-lucide-x"
                  size="xs"
                  color="neutral"
                  variant="ghost"
                  square
                  @click="() => { form.questions.splice(i, 1) }"
                />
              </div>
              <div
                v-if="openQuestion === i && !longTurn"
                class="grid gap-3 ps-7 pt-2 pb-1"
              >
                <UFormField
                  label="Examiner audio"
                  help="An address (https://…) or an upload. Without one, the voice is generated once."
                >
                  <div class="flex items-center gap-2">
                    <UInput
                      v-model="q.audioRef as string"
                      placeholder="https://…/question.mp3"
                      class="flex-1"
                    />
                    <audio
                      v-if="q.audioRef"
                      :src="q.audioRef"
                      controls
                      preload="none"
                      class="h-8 max-w-56"
                    />
                  </div>
                </UFormField>
                <UFormField
                  label="Sample answer"
                  help="Shown after the attempt and in AI feedback, so the AI does not write one."
                >
                  <UTextarea
                    v-model="q.sampleAnswer"
                    :rows="3"
                    autoresize
                    class="w-full"
                  />
                </UFormField>
              </div>
            </li>
          </ol>
          <template #footer>
            <div class="flex gap-2">
              <UInput
                v-model="newQuestion"
                placeholder="Type a question and press Enter"
                class="flex-1"
                @keydown.enter.prevent="addQuestion"
              />
              <UButton
                icon="i-lucide-plus"
                label="Add"
                :disabled="!newQuestion.trim()"
                @click="addQuestion"
              />
            </div>
          </template>
        </UCard>
      </div>
      <UCard class="lg:sticky lg:top-4">
        <template #header>
          <p class="font-semibold text-highlighted">
            Details
          </p>
        </template>
        <div class="grid gap-3">
          <UFormField label="Title">
            <UInput
              v-model="form.title"
              class="w-full"
            />
          </UFormField>
          <UFormField label="Part">
            <USelect
              v-model="form.partNumber"
              :items="partNumbersOf(part?.exam, 'SPEAKING').map(n => ({ label: speakingPartLabel(n, part?.exam), value: n }))"
              class="w-full"
            />
          </UFormField>
          <UFormField
            label="Preparation (seconds)"
            help="Per question in Parts 1.1 and 1.2."
          >
            <UInputNumber
              v-model="form.prepSeconds"
              :min="0"
              :max="600"
              :placeholder="ielts ? (form.partNumber === 2 ? '60' : '3') : form.partNumber >= 3 ? '60' : '5'"
              class="w-full"
            />
          </UFormField>
          <UFormField label="Speaking time (seconds)">
            <UInputNumber
              v-model="form.speakSeconds"
              :min="0"
              :max="900"
              :placeholder="ielts ? (form.partNumber === 2 ? '120' : form.partNumber === 3 ? '60' : '30') : form.partNumber >= 3 ? '120' : '30'"
              class="w-full"
            />
          </UFormField>
        </div>
      </UCard>
    </div>
  </AppPage>
</template>
